const fs=require('fs'),path=require('path'),{ESLint}=require('eslint');
(async()=>{
 const b=JSON.parse(fs.readFileSync('docs/remediation/design/W35.01/baseline.json','utf8'));
 const results=await new ESLint().lintFiles(b.owned_before.map(p=>p.path));
 const counts=signatures=>{const map=new Map();for(const s of signatures){const k=JSON.stringify(s);map.set(k,(map.get(k)||0)+1);}return map;};
 const rows=results.map(r=>{const file=path.relative(process.cwd(),r.filePath).replaceAll('\\','/'),base=b.lint.rows.find(x=>x.path===file),actual=counts(r.messages.filter(m=>m.severity===1).map(m=>[m.ruleId,m.message])),prior=counts(base.signatures),added=[...actual].filter(([k,n])=>n>(prior.get(k)||0)).map(([k,n])=>({signature:JSON.parse(k),added:n-(prior.get(k)||0)}));return{path:file,errors:r.errorCount,warnings:r.warningCount,signatures:[...actual].sort(([a],[b])=>a.localeCompare(b)).map(([k,count])=>({signature:JSON.parse(k),count})),added};});
 const errors=rows.reduce((n,r)=>n+r.errors,0),warnings=rows.reduce((n,r)=>n+r.warnings,0),passed=errors===0&&warnings<=b.lint.warnings&&rows.every(r=>r.added.length===0);
 console.log(JSON.stringify({at:new Date().toISOString(),baseline_errors:b.lint.errors,baseline_warnings:b.lint.warnings,errors,warnings,rows,passed}));
 if(!passed)process.exitCode=1;
})().catch(e=>{console.error(e);process.exitCode=1;});
